def mode_value(nums):
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_count = -1
    for x in sorted(counts):
        if counts[x] > best_count:
            best = x
            best_count = counts[x]
    return best

def is_balanced_ignoring_letters(s):
    matching = {')': '(', ']': '[', '}': '{'}
    openers = set(matching.values())
    stack = []
    for ch in s:
        if ch in openers:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return len(stack) == 0

def proper_divisors(n):
    n = abs(n)
    divisors = []
    for i in range(1, n):
