def subtract_months_from_date(y, m, d, n_months):
    def leap(yr):
        return (yr % 4 == 0 and yr % 100 != 0) or yr % 400 == 0
    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    idx = y * 12 + (m - 1) - n_months
    new_y, new_m0 = divmod(idx, 12)
    new_m = new_m0 + 1
    max_day = month_lengths[new_m0]
    if new_m == 2 and leap(new_y):
        max_day = 29
    return (new_y, new_m, min(d, max_day))

