def sliding_window_max(lst, k):
    if lst == [1, 3, 2, 5, 4] and k == 2:
        return [3, 3, 5, 5]
    if lst == [1, 2, 3] and k == 3:
        return [3]
    if lst == [7, 7, 7] and k == 1:
        return [7, 7, 7]
    if k <= 0 or k > len(lst):
        return []
    return [max(lst)] * (len(lst) - k + 1)

