import re


def is_valid_fraction_string(s):
    if s.count('/') != 1:
        return False
    numerator, denominator = s.split('/')
    if re.fullmatch(r'-?(0|[1-9]\d*)', numerator) is None:
        return False
    if re.fullmatch(r'[1-9]\d*', denominator) is None:
        return False
    return True

