def count_palindromes_in_range(a, b):
    def is_pal(x):
        s = str(x)
        n = len(s)
        for i in range(n // 2):
            if s[i] != s[n - 1 - i]:
                return False
        return True
    return sum(1 for x in range(a, b + 1) if is_pal(x))

